+import assert from "node:assert/strict";
+import { spawnSync } from "node:child_process";
+import { test } from "node:test";
+import { fileURLToPath } from "node:url";
+
+// End-to-end acceptance for the --since filter: the CLI is the public interface.
+const SCRIPT = fileURLToPath(new URL("../scripts/log-summary.mjs", import.meta.url));
+
+function run(...args) {
+  return spawnSync(process.execPath, [SCRIPT, ...args], { encoding: "utf8" });
+}
+
+test("acceptance: --since keeps only events at or after the timestamp", () => {
+  const result = run("--since", "2026-01-04T09:06:00Z", "fixtures/events.jsonl");
+  assert.equal(result.status, 0, result.stderr);
+  const summary = JSON.parse(result.stdout);
+  assert.deepEqual(summary.levels, { error: 1, info: 1 });
+  assert.equal(summary.first, "2026-01-04T09:06:00Z");
+  assert.equal(summary.last, "2026-01-04T09:07:00Z");
+});
+
+test("acceptance: an unparseable --since is an error", () => {
+  const result = run("--since", "not-a-date", "fixtures/events.jsonl");
+  assert.equal(result.status, 1);
+  assert.equal(result.stdout, "");
+  assert.match(result.stderr, /invalid --since date: "not-a-date"/);
+});
+
+test("acceptance: no arguments still summarizes the whole fixture", () => {
+  const result = run();
+  assert.equal(result.status, 0, result.stderr);
+  const summary = JSON.parse(result.stdout);
+  assert.deepEqual(summary.levels, { info: 2, warn: 1, error: 1 });
+  assert.equal(summary.first, "2026-01-04T09:00:00Z");
+  assert.equal(summary.last, "2026-01-04T09:07:00Z");
+});
